<?php
namespace EIPSI\AssessmentEditor;
final class Flow {
    public static function messages(): array {return array('expired'=>'La sesión anterior venció. Empezá nuevamente desde la primera página.','expired_saved'=>'Las respuestas parciales de la sesión anterior quedaron guardadas. Empezá nuevamente desde la primera página.','processing'=>'Actualizando sesión…','updated'=>'Sesión actualizada.','completed'=>'Respuestas guardadas correctamente.','invalid'=>'No se pudieron procesar tus respuestas. Volvé a intentarlo.','delivery_error'=>'No se pudo confirmar el guardado de tus respuestas. Volvé a intentarlo con el mismo botón.','discard_accept'=>'Aceptar','discard_cancel'=>'Cancelar','discard_label'=>'Descartar respuesta','discard_confirm'=>'¿Descartar esta respuesta? Se eliminarán la sesión y las respuestas de esta evaluación para comenzar desde cero.','discarded'=>'Respuesta descartada. Podés empezar desde el comienzo.','progress'=>'Página [ACTUAL] de [TOTAL]','progress_accessible'=>'Progreso por páginas');}
    const UNITS=array('minutes'=>60,'hours'=>3600,'days'=>86400,'weeks'=>604800,'months'=>2592000);
    public static function defaults(): array {return array('pages'=>array(),'allow_back'=>true,'navigation_labels'=>array('back'=>'','next'=>'','finish'=>''),'progress'=>'pages','completion'=>array('title'=>'Gracias por responder','message_html'=>'<p>Gracias por completar la evaluación.</p>','image_url'=>'','button_label'=>'','allow_restart'=>true),'save_continue'=>array('enabled'=>false,'window'=>array('value'=>7,'unit'=>'days')),'metadata_profile'=>'basic');}
    private static function pageId(string $id): string {if(strlen($id)<=97)return 'PG_'.$id;$h=2166136261;for($i=0;$i<strlen($id);$i++)$h=(($h^ord($id[$i]))*16777619)&0xffffffff;return 'PG_'.substr($id,0,80).'_'.sprintf('%08x',$h);}
    public static function normalize(array $d): array {
        $f=$d['flow']??self::defaults();if(!is_array($f))Definition::fail('Invalid flow');if(isset($f['messages'])){if(!is_array($f['messages'])||array_diff(array_keys($f['messages']),array_keys(self::messages())))Definition::fail('Invalid message keys');foreach($f['messages'] as $message)if(!is_string($message)||strlen($message)>8000||preg_match('//u',$message)!==1)Definition::fail('Invalid message');}$f['navigation_labels']=$f['navigation_labels']??array('back'=>'','next'=>'','finish'=>'');Definition::fields($f,array_merge(array_keys(self::defaults()),array_merge(array_merge(array_key_exists('messages',$f)?array('messages'):array(),array_key_exists('design',$f)?array('design'):array()),array_merge(array_key_exists('show_title',$f)?array('show_title'):array(),array_key_exists('allow_discard',$f)?array('allow_discard'):array()))));if(array_key_exists('allow_discard',$f)&&!is_bool($f['allow_discard']))Definition::fail('Invalid discard policy');if(array_key_exists('design',$f))self::validateDesign($f['design']);if(array_key_exists('show_title',$f)&&!is_bool($f['show_title']))Definition::fail('Invalid title visibility');if(!is_array($f['navigation_labels']))Definition::fail('Invalid navigation labels');Definition::fields($f['navigation_labels'],array('back','next','finish'));foreach($f['navigation_labels'] as $label)if(!is_string($label)||strlen($label)>200)Definition::fail('Invalid navigation label');
        if(!is_bool($f['allow_back'])||!in_array($f['progress'],array('none','bar','pages','both'),true)||!in_array($f['metadata_profile'],array('basic','standard','detailed'),true))Definition::fail('Invalid flow policy');
        if(!is_array($f['completion']))Definition::fail('Invalid completion');$c=&$f['completion'];Definition::fields($c,array('title','message_html','image_url','button_label','allow_restart'));
        foreach(array('title'=>200,'message_html'=>80000,'image_url'=>2000,'button_label'=>200) as $k=>$max)if(!is_string($c[$k])||strlen($c[$k])>$max)Definition::fail('Invalid completion content');
        if(!is_bool($c['allow_restart'])||($c['image_url']!==''&&!preg_match('~^(?:https?://|/(?!/))~i',$c['image_url'])))Definition::fail('Invalid completion image/restart');$c['message_html']=RichText::sanitize($c['message_html']);unset($c);
        if(!is_array($f['save_continue']))Definition::fail('Invalid recovery');Definition::fields($f['save_continue'],array('enabled','window'));$w=$f['save_continue']['window'];if(!is_array($w))Definition::fail('Invalid recovery window');Definition::fields($w,array('value','unit'));
        if(!is_bool($f['save_continue']['enabled'])||!is_int($w['value'])||$w['value']<1||!isset(self::UNITS[$w['unit']])||$w['value']*self::UNITS[$w['unit']]>157680000)Definition::fail('Invalid recovery window');
        if(!is_array($f['pages'])||($f['pages']&&array_keys($f['pages'])!==range(0,count($f['pages'])-1)))Definition::fail('Invalid pages');$prior=array();
        foreach($f['pages'] as $p){if(!is_array($p))Definition::fail('Invalid page');Definition::fields($p,array('id','boundary_id','title','description_html'));Definition::id($p['id']);if(isset($prior[$p['id']]))Definition::fail('Duplicate page identity');if($p['boundary_id']!==null)Definition::id($p['boundary_id']);foreach(array('title'=>200,'description_html'=>80000) as $k=>$max)if(!is_string($p[$k])||strlen($p[$k])>$max)Definition::fail('Invalid page content');$p['description_html']=RichText::sanitize($p['description_html']);$prior[$p['id']]=$p;}
        $start=null;foreach($prior as $p)if($p['boundary_id']===null){if($start!==null)Definition::fail('Duplicate start page');$start=$p['id'];}
        $boundaries=array(null);foreach($d['elements'] as $e)if($e['type']==='page_break')$boundaries[]=$e['id'];$f['pages']=array();$generated=array();
        foreach($boundaries as $b){$id=$b===null?($start??self::pageId($d['id'])):self::pageId($b);if(isset($generated[$id]))Definition::fail('Duplicate derived page identity');$generated[$id]=true;$p=$prior[$id]??array('id'=>$id,'boundary_id'=>$b,'title'=>'','description_html'=>'');if($p['boundary_id']!==$b)Definition::fail('Invalid page boundary');$f['pages'][]=$p;}$d['flow']=$f;return $d;
    }
    private static function validateDesign($d): void {
        if(!is_array($d))Definition::fail('Invalid design');
        Definition::fields($d,array('preset','primary','background','text','button_text','font','font_size','width','padding','gap','radius','shadow','navigation_alignment'));
        if(!in_array($d['preset'],array('Clinical Blue','Minimal White','Warm Neutral','Serene Teal'),true)||!in_array($d['font'],array('system','sans','serif'),true)||!in_array($d['navigation_alignment'],array('edges','center'),true)||!is_bool($d['shadow']))Definition::fail('Invalid design choice');
        foreach(array('primary','background','text','button_text') as $key)if(!is_string($d[$key])||!preg_match('/^#[0-9a-fA-F]{6}$/D',$d[$key]))Definition::fail('Invalid design color');
        foreach(array('font_size'=>array(12,32),'width'=>array(320,1400),'padding'=>array(0,96),'gap'=>array(8,80),'radius'=>array(0,32)) as $key=>$bounds)if(!is_int($d[$key])||$d[$key]<$bounds[0]||$d[$key]>$bounds[1])Definition::fail('Invalid design dimension');
    }
    public static function retention(array $d): int {return $d['flow']['save_continue']['window']['value']*self::UNITS[$d['flow']['save_continue']['window']['unit']];}
}
